// SPDX-License-Identifier: AGPL-3.0-or-later  ·  Copyright (c) 2026 John Chen
// CHIMNEY: smoke from the hearth, up a flue, out of a slim stack. The owner: a campfire perched on the tip of a stack
// is wrong, and a wide crown on a thin shaft (a lollipop) looks bad. A real chimney burns at the BOTTOM, in the
// hearth: the campfire sits in the firebox at floor level (a hay bale hidden in the floor under it makes the smoke
// rise ~24 blocks), the smoke rises through a 1 x 1 flue of air, walled on all four sides at every level, through the
// floors and the roof, and leaves by the open mouth at the top. Where the flue has no wall beside it (in a room, above
// the roof) an open trapdoor lying flat against the flue is a thin wall: four of them make a slim 1 x 1 pipe (iron or
// copper trapdoors read as a tin stovepipe, wood as a boxed flue), or use masonry for a brick stack.
//   hearthPlan({ x, y, z, open, top, material, thin, lintel }) -> [[x, y, z, block, state], ...]
//   x, y, z: the campfire's cell (on the room's floor level); open: the side the firebox opens to (into the room);
//   top: the flue's last course (the mouth is open above it; put it 1-2 over the roof where the flue leaves it);
//   material: { full, stairs } (roofs.mjs materialOf) for the firebox and any masonry; thin: "iron" | "copper" | a wood
//   name | null: walls beside the flue that are air get an open trapdoor of that kind (null: masonry);
//   current(x, y, z): the block name there now ("air" if none), so the house's walls and floors are kept as the flue's
//   walls below the roof; roofY (auto: the first course with a roof stair or slab beside the flue): from there up the
//   flue's walls are always the chimney's own, so the stack runs solid through the roof. mouth: cut the hearth's
//   opening through a wall (the fire set outside the wall line, in an exterior chimney).
const DIRS = { north: [0, -1], south: [0, 1], east: [1, 0], west: [-1, 0] };
const OPP = { north: "south", south: "north", east: "west", west: "east" };
const AIRY = /(^|_)air$|glass|pane|_bars$|fence|_door$|torch|lantern|chain|sign|banner|carpet|flower|button|ladder|vine/;   // not a wall

export const trapdoorOf = (kind) => (!kind ? null : /trapdoor$/.test(kind) ? kind : `${kind.replace(/_block$/, "")}_trapdoor`);

export function hearthPlan({ x, y, z, open = "south", top, material, thin = null, lintel = true, roofY, mouth = false, current = () => "air" }) {
  const out = [], td = trapdoorOf(thin), [ox, oz] = DIRS[open];
  const nm = (cx, cy, cz) => String(current(cx, cy, cz)).replace(/^minecraft:/, "");
  const wallish = (cx, cy, cz) => !AIRY.test(nm(cx, cy, cz));
  // where the roof starts beside the flue (the first course with a roof stair or slab next to it): from there up the
  // flue's four walls are the chimney's own, never the roof's tiles (the roof stops against the stack)
  if (roofY == null) {
    roofY = Infinity;
    for (let cy = y + 2; cy <= top && roofY === Infinity; cy++) for (const [dx, dz] of Object.values(DIRS)) if (/_stairs$|_slab$/.test(nm(x + dx, cy, z + dz))) { roofY = cy; break; }
  }
  // the fire: hay set into the floor, the campfire on it, lit, smoke as a signal fire
  out.push([x, y - 1, z, "hay_block", { axis: "y" }]);
  out.push([x, y, z, "campfire", { lit: "true", signal_fire: "true", facing: open, waterlogged: "false" }]);
  // the firebox: masonry on the back and both sides at the fire's level, its mouth open to the room; hay walled too
  for (const [d, [dx, dz]] of Object.entries(DIRS)) {
    if (d !== open) out.push([x + dx, y, z + dz, material.full, undefined]);
    if (!wallish(x + dx, y - 1, z + dz)) out.push([x + dx, y - 1, z + dz, material.full, undefined]);
  }
  if (mouth) out.push([x + ox, y, z + oz, "air", undefined]);                      // the hearth's opening cut through the wall
  // the lintel over the mouth (an upside-down stair facing the room) closes the flue's front from the next course up
  // the flue: air from the course above the fire to the top, every side walled (kept walls below the roof; from the roof
  // up the chimney's own masonry, or a thin trapdoor where there is only air beside it)
  for (let cy = y + 1; cy <= top; cy++) {
    out.push([x, cy, z, "air", undefined]);
    for (const [d, [dx, dz]] of Object.entries(DIRS)) {
      const nx = x + dx, nz = z + dz, here = nm(nx, cy, nz);
      if (cy === y + 1 && d === open) { out.push([nx, cy, nz, ...(lintel ? [material.stairs, { facing: OPP[open], half: "top", shape: "straight", waterlogged: "false" }] : [material.full, undefined])]); continue; }
      if (cy < roofY && wallish(nx, cy, nz)) continue;                           // a wall or a floor of the house
      if (cy >= roofY && wallish(nx, cy, nz) && here === material.full) continue;  // already the stack
      if (td && !wallish(nx, cy, nz)) out.push([nx, cy, nz, td, { facing: d, half: "bottom", open: "true", powered: "false", waterlogged: "false" }]);
      else out.push([nx, cy, nz, material.full, undefined]);
    }
  }
  return out;
}

/** Is a lit campfire a proper hearth fire? Its smoke must find an open flue (air or a thin trapdoor's cell) straight
 *  up to the sky, walled on all four sides above the firebox, and its hay (if any) hidden. Returns [] or the faults. */
